}

export function searchIndex(nodeArray: ChildNode[], folderZip: JSZip): IRoom[] {
	// allRooms = [Promise<IRoom[], Promise<IRoom[], ...]
	let allRooms: any[] = [];
	for (const childNode of nodeArray) {
		if (childNode.nodeName === "td" && "attrs" in childNode &&
			childNode.attrs[0].value === "views-field views-field-field-building-image") {
			searchForRoomsinBuilding(childNode, folderZip)
				.then((resultRooms) => {
					allRooms = allRooms.concat(resultRooms);
				});
			allRooms.push(searchForRoomsinBuilding(childNode, folderZip));

		} else if ("childNodes" in childNode) {
			allRooms = allRooms.concat(searchIndex(childNode.childNodes, folderZip));
		}
	}
	return allRooms; // [IRoom[], IRoom[]]
}

async function searchForRoomsinBuilding(childNode: Element, folderZip: JSZip): Promise<IRoom[]> {
	let promisedRoomArrayForOneBuilding: IRoom[] = [];
	// Get directory
	let tempDirectory = "";
	if("attrs" in childNode.childNodes[1]) {
		tempDirectory = childNode.childNodes[1].attrs[0].value;
	}
	// Get parent node to get other information for 1 building
	const trNode = childNode.parentNode;
	const extractedBuildingInfo = extractBuildingInfo(trNode as Element);
	const tempShortName = extractedBuildingInfo.tempShortName;
	const tempFullName = extractedBuildingInfo.tempFullName;
	const tempAddress = extractedBuildingInfo.tempAddress;
	const geoLocationObject = await findGeolocation(tempAddress);

	// Using JSZip to access files for additional information
	// Access the files
	let buildingHtm = folderZip.file(tempDirectory.substring(2));
	// Rejects if index.htm does not exist
	if (buildingHtm === null) {
		throw new InsightError("building file does not exist");
	}

	// Convert building.htm to string and retrieve information
	const buildingFileContent = await buildingHtm.async("string");
	const buildingDocument = parse(buildingFileContent);
	// DFS for table objects
	let buildingInfo = searchForBuildingInformation(buildingDocument.childNodes, []);
	// Proceed only if building has rooms
	if (buildingInfo.length !== 0) {
		buildingInfo.forEach((roomInfo) => {
			let room: IRoom = {
				fullname: tempFullName,
				shortname: tempShortName,
				number: roomInfo["tempRoomNumber"],
				name: tempShortName + roomInfo["tempRoom"],
				address: tempAddress,
				lat: geoLocationObject["lat"],
				lon: geoLocationObject["lon"],
				seats: parseInt(roomInfo["tempCapacity"], 10),
				type: roomInfo["tempRoomType"],
				furniture: roomInfo["tempFurnitureType"],
				href: roomInfo["tempHref"]
			};
			promisedRoomArrayForOneBuilding.push(room);
		});
	}
	return Promise.resolve(promisedRoomArrayForOneBuilding);
}


function extractBuildingInfo(trNode: Element) {
	let tempShortName = "";
	let tempFullName = "";
	let tempAddress = "";
	trNode.childNodes.forEach((trChild) => {
		if ("attrs" in trChild && trChild.attrs[0].value === "views-field views-field-field-building-code") {
			tempShortName = extractValue(trChild, tempShortName);
		} else if ("attrs" in trChild && trChild.attrs[0].value === "views-field views-field-title") {
			if ("childNodes" in trChild.childNodes[1] && "value" in trChild.childNodes[1].childNodes[0]) {
				tempFullName = trChild.childNodes[1].childNodes[0].value;
			}
		} else if ("attrs" in trChild &&
			trChild.attrs[0].value === "views-field views-field-field-building-address") {
			tempAddress = extractValue(trChild, tempShortName);
		}
	});
	return {tempShortName, tempFullName, tempAddress};
}

function extractValue(trChild: Element, tempShortName: string) {
	if ("value" in trChild.childNodes[0]) {
		tempShortName = trChild.childNodes[0].value.trim();
	}
	return tempShortName;
}

function findGeolocation(tempAddress: string): Promise<any>{
	return new Promise(function(resolve, reject) {
		http.get(encodeURI("http://cs310.students.cs.ubc.ca:11316/api/v1/project_team573/" + tempAddress), (res) => {
			let rawData = "";
			res.on("data", (chunk) => {
				rawData += chunk;
			});
			res.on("end", () => {
				let parsedData;
				try {
					parsedData = JSON.parse(rawData);
				} catch (error) {
					return reject(error);
				}
				return resolve(parsedData);
			});
		}).on("error", (e) => {
			console.error("Got error: ${e.message}");
		});
	});
}

function searchForBuildingInformation(nodeArray: ChildNode[], resultArray: any[]): any[] {
	nodeArray.forEach((childNode) => {
		if (childNode.nodeName === "td" && "attrs" in childNode &&
			childNode.attrs[0].value === "views-field views-field-nothing") {
			// Get directory
			let tempHref = "";
			if("attrs" in childNode.childNodes[1]) {
				tempHref = childNode.childNodes[1].attrs[0].value;
			}
			// Get parent node to get other information for 1 building
			const trNode = childNode.parentNode;
			let tempRoomNumber = "";
			let tempCapacity = "";
			let tempFurnitureType = "";
			let tempRoomType = "";
			trNode.childNodes.forEach((trChild) => {
				if ("attrs" in trChild && trChild.attrs[0].value === "views-field views-field-field-room-number"){
					if ("childNodes" in trChild.childNodes[1] && "value" in trChild.childNodes[1].childNodes[0]) {
						tempRoomNumber = trChild.childNodes[1].childNodes[0].value;
					}
				} else if ("attrs" in trChild &&
					trChild.attrs[0].value === "views-field views-field-field-room-capacity"){
					tempCapacity = extractValue(trChild, tempCapacity);
				} else if ("attrs" in trChild &&
					trChild.attrs[0].value === "views-field views-field-field-room-furniture"){
					tempFurnitureType = extractValue(trChild, tempFurnitureType);
				} else if ("attrs" in trChild && trChild.attrs[0].value === "views-field views-field-field-room-type"){
					tempRoomType = extractValue(trChild, tempRoomType);
				}
			});
			let buildingInfo = {
				tempRoomNumber,
				tempCapacity,
				tempFurnitureType,
				tempRoomType,
				tempHref
			};
			resultArray.push(buildingInfo);
		} else if ("childNodes" in childNode) {
			searchForBuildingInformation(childNode.childNodes, resultArray);
		}
	});
	// Base Case
	return resultArray;
}

import {writeSectionsAndRooms} from "./IUtility";
import JSZip from "jszip";
import {ISection} from "../interface/IKind";

// Helper function for parseFileContent
// Returns true if a section object is valid and can be parsed into a section
export function validSection(sectionObj: any): boolean {
	return (
		sectionObj.subject != null &&
		sectionObj.course != null &&
		sectionObj.avg != null &&
		sectionObj.professor != null &&
		sectionObj.title != null &&
		sectionObj.pass != null &&
		sectionObj.fail != null &&
		sectionObj.audit != null &&
		sectionObj.id != null &&
		sectionObj.year != null
	);
}

// Parses a section object into a section
async function parseSectionObj(sectionObj: any): Promise<ISection> {
	// create ISection from fileContent
	const section: ISection = {
		dept: sectionObj.subject,
		id: sectionObj.course,
		avg: sectionObj.avg,
		instructor: sectionObj.professor,
		title: sectionObj.title,
		pass: sectionObj.pass,
		fail: sectionObj.fail,
		audit: sectionObj.audit,
		uuid: sectionObj.id.toString(),
		year: parseInt(sectionObj.year, 10),
	};
	if (sectionObj.section === "overall") {
		section.year = 1900;
	}
	return Promise.resolve(section);
}

// Helper function for parseFile
// Parses a JSON file containing course sections into an array of ISections
export async function parseJsonToCourseSections(fileContent: string): Promise<ISection[]> {
	const promises: any[] = [];
	try {
		// lowercase for more robust key handling
		let object = JSON.parse(fileContent.toLocaleLowerCase());
		object = object.result;
		// return if valid or not
		object.forEach((sectionObj: any) => {
			// add section to sections, if it is valid
			if (validSection(sectionObj)) {
				promises.push(parseSectionObj(sectionObj));
			}
		});
	} catch (error) {
		// ignore invalid JSONs
	}
	return Promise.all(promises);
}

// Parses a JSZip object representing a file into course sections and writes sections to filePath in JSON format
export async function parseAndWriteJsonFile(file: JSZip.JSZipObject, filePath: string): Promise<ISection[]> {
	return file.async("string").then(async (fileContent) => {
		// parse file's contents
		// lowercase string for robust key handling
		let courseSections: ISection[] = [];
		return parseJsonToCourseSections(fileContent).then((awaited) => {
			if (awaited.length > 0) {
				courseSections = courseSections.concat(awaited);
				writeSectionsAndRooms(courseSections, filePath);
			}
			return Promise.all<ISection[]>(courseSections);
		});
	});
}

import fs from "fs";
import {IElement} from "../interface/IElement";
import {InsightDataset, InsightResult} from "../IInsightFacade";
import {IKind} from "../interface/IKind";
import {ApplyToken} from "./IValidate";
import Decimal from "decimal.js";

// Writes course sections to a JSON file
export async function writeSectionsAndRooms(kindInstance: IKind[], filePath: string): Promise<void> {
	await fs.writeFile(filePath, JSON.stringify(kindInstance), () => 0);
	return Promise.resolve();
}

// Get keys from a collection of datasets
export function getKeys(datasets: Map<string, IElement>) {
	const keys: string[] = [];
	datasets.forEach((value: IElement, key: string) => {
		keys.push(key);
	});
	return keys;
}

// Get InsightDatasets from a collection of datasets
export function getDatasets(datasets: Map<string, IElement>): InsightDataset[] {
	const ret: InsightDataset[] = [];
	for (const entry of datasets.entries()) {
		ret.push(entry[1].info);
	}
	return ret;
}

// Converts a list of IKinds into InsightResults with specified fields.
export function createResultsWithSpecifiedFields(kinds: IKind[], specifiedFields: string[]): InsightResult[] {
	let results: InsightResult[] = [];
	for (const item of kinds) {
		const resultElement = createResultWithSpecifiedFields(item, specifiedFields);
		results.push(resultElement);
	}
	return results;
}

// Converts an IKind into an InsightResult with specified fields.
function createResultWithSpecifiedFields(item: IKind, specifiedFields: string[]): InsightResult {
	let resultElement: InsightResult = {};
	for (const columnName of specifiedFields) {
		const splitKey = columnName.split("_");
		const specifiedField = splitKey[1];
		resultElement[columnName] = item[specifiedField as keyof IKind];
	}
	return resultElement;
}

// Returns a result with only the specified columns
export function selectFieldsFromResult(result: InsightResult, columnsArray: string[]): InsightResult {
	let newResult: InsightResult = {};
	for (const column of columnsArray) {
		newResult[column] = result[column];
	}
	return newResult;
}

// Returns kinds grouped by a groupKeys tuple
export function createGroupsFromKinds(kinds: IKind[], groupKeys: string[]): Map<string, IKind[]> {
	let groups = new Map<string, IKind[]>();
	for (const item of kinds) {
		let groupKey = getKindGroupValues(item, groupKeys);
		let group = groups.get(groupKey);
		if (group) {
			group.push(item);
			groups.set(groupKey, group);
		} else {
			groups.set(groupKey, [item]);
		}
	}
	return groups;
}

// Returns the id tuple for the group that a kind belongs to
function getKindGroupValues(kind: IKind, groupKeys: string[]): string {
	let groupValues: any[] = [];
	for (const groupKey of groupKeys) {
		let groupField = groupKey.split("_")[1];
		groupValues.push(kind[groupField as keyof IKind]);
	}
	return groupValues.toString();
}

// Applies applyRules to a group of IKinds and returns an InsightResult
export function applyRulesToGroup(group: IKind[], groupKeys: string[], applyRules: any[]): InsightResult {
	let result: InsightResult = {};
	let elem = group[0];

	// Add keys from groupKeys to result
	for (const groupKey of groupKeys) {
		let field = groupKey.split("_")[1];
		result[groupKey] = elem[field as keyof IKind];
	}

	// Add applyKeys and their values to result
	for (const applyRule of applyRules) {
		let applyKey = Object.keys(applyRule)[0];
		let applyToken = Object.keys(applyRule[applyKey])[0];
		let field = applyRule[applyKey][applyToken].split("_")[1]; // Key to apply rule on
		result[applyKey] = applyTokenToGroup(applyToken, field, group);
	}
	return result;
}

// Returns the value of an applyToken applied to a field for a group of kinds
function applyTokenToGroup(applyToken: string, field: string, kinds: IKind[]): any {
	if (applyToken === ApplyToken.AVG || applyToken === ApplyToken.SUM) {
		let sum = new Decimal(0);
		for (const item of kinds) {
			sum = sum.add(new Decimal(item[field as keyof IKind]));
		}
		if (applyToken === ApplyToken.AVG) {
			let avg = sum.toNumber() / kinds.length;
			return Number(avg.toFixed(2));
		}
		return Number(sum.toFixed(2));
	} else if (applyToken === ApplyToken.MAX) {
		let max = kinds[0][field as keyof IKind];
		for (let i = 1; i < kinds.length; i++) {
			let val = kinds[i][field as keyof IKind];
			if (val > max) {
				max = val;
			}
		}
		return max;
	} else if (applyToken === ApplyToken.MIN) {
		let min = kinds[0][field as keyof IKind];
		for (let i = 1; i < kinds.length; i++) {
			let val = kinds[i][field as keyof IKind];
			if (val < min) {
				min = val;
			}
		}
		return min;
	} else {
		// COUNT
		let uniqueValues = new Map<any, number>();
		for (const item of kinds) {
			let value = item[field as keyof IKind];
			let count = uniqueValues.get(value);
			if (count) {
				uniqueValues.set(value, count + 1);
			} else {
				uniqueValues.set(value, 1);
			}
		}
		return uniqueValues;
	}
}

import {InsightDatasetKind, InsightError, InsightResult} from "../IInsightFacade";
import {IQueryValidator} from "./IQueryValidator";

// File to validate inputs for InsightFacade

const S_FIELDS = [
	"dept",
	"id",
	"instructor",
	"title",
	"uuid",
	"fullname",
	"shortname",
	"number",
	"name",
	"address",
	"type",
	"furniture",
	"href",
];
const M_FIELDS = ["avg", "pass", "fail", "audit", "year", "lat", "lon", "seats"];
const COURSES_FIELDS = ["avg", "pass", "fail", "audit", "year", "dept", "id", "instructor", "title", "uuid"];
const ROOMS_FIELDS = [
	"lat",
	"lon",
	"seats",
	"fullname",
	"shortname",
	"number",
	"name",
	"address",
	"type",
	"furniture",
	"href",
];

export enum KeyType {
	M_KEY = "M KEY",
	S_KEY = "S KEY",
	ANY_KEY = "ANY KEY",
	KEY = "KEY",
	APPLY_KEY = "APPLY KEY",
}

export enum Direction {
	UP = "UP", // Represents ascending order
	DOWN = "DOWN", // Represents descending order
}

export enum ApplyToken {
	COUNT = "COUNT",
	SUM = "SUM",
	MIN = "MIN",
	MAX = "MAX",
	AVG = "AVG",
}

// Throws InsightError if field is not a valid field for a keyType
export function checkField(field: string, keyType: KeyType): void {
	if (keyType === KeyType.M_KEY) {
		if (!isMField(field)) {
			throw new InsightError("Invalid MField: " + field);
		}
	} else if (keyType === KeyType.S_KEY) {
		if (!isSField(field)) {
			throw new InsightError("Invalid SField: " + field);
		}
	} else if (keyType === KeyType.KEY) {
		if (!isMField(field) && !isSField(field)) {
			throw new InsightError("Invalid key field: " + field);
		}
	} else {
		throw new Error("Invalid key type passed to checkField");
	}
}

// Returns true if a field is a courses field
export function isCoursesField(field: string): boolean {
	return COURSES_FIELDS.includes(field);
}

// Returns true if a field is a rooms field
export function isRoomsField(field: string): boolean {
	return ROOMS_FIELDS.includes(field);
}

// Returns true if a field is an SField (string field)
function isSField(field: string) {
	return S_FIELDS.includes(field);
}

// Returns true if a field is an MField (numeric field)
function isMField(field: string) {
	return M_FIELDS.includes(field);
}

// Checks that a string is a valid apply token
export function checkValidApplyToken(str: string) {
	if (!Object.keys(ApplyToken).includes(str)) {
		throw new InsightError("Invalid APPLY token");
	}
}

// Returns true if string has an underscore
export function hasUnderscore(str: string): boolean {
	return str.search("_+") > -1;
}

// Returns true if a string is not just whitespace characters
export function nonWhitespace(str: string): boolean {
	return str.search("[^\\t\\r\\n\\v\\f ]+") > -1;
}

// Check that an object has the correct length. Otherwise, throws InsightError with object's name
export function checkObjectLength(obj: any, len: number, name: string): void {
	const objectLength = Object.keys(obj).length;
	if (objectLength !== len) {
		throw new InsightError(name + " should only have " + len + " key(s), but has " + objectLength);
	}
}

// Check that an object is non-empty array.
// Otherwise, throws error with name
export function checkNonEmptyArray(obj: any, name: string): void {
	if (obj.length <= 0 || !Array.isArray(obj)) {
		// Reject if COLUMN array is empty
		throw new InsightError(name + " must be a non-empty array");
	}
}

// Check if all entries of subset appear in set. If not, throws InsightError.
export function checkSubset(subset: any[], set: any[], subsetName: string, setName: string): void {
	subset.forEach((item: any) => {
		checkString(item, subsetName);
		if (!set.includes(item)) {
			throw new InsightError(subsetName + " element must be in " + setName);
		}
	});
}

// Checks that a field is a string
export function checkString(field: any, errorLoc: string): void {
	if (typeof field !== "string") {
		throw new InsightError(errorLoc + " is not a string");
	}
}

// Returns true if field matches (\*)?[^\*]*(\*)? and field is a string
// ie. asterisk is only at beginning or end, and in each location at most once
export function checkValidSCompArg(field: any): void {
	// Type check
	checkString(field, "SComparison Value");

	// Semantics check
	if (field.startsWith("*")) {
		field = field.substring(1);
	}
	if (field.endsWith("*")) {
		field = field.substring(0, field.length - 1);
	}
	let invalid = field.includes("*");
	if (invalid) {
		throw new InsightError("Asterisks (*) can only appear as the first or last characters of input strings");
	}
}

// Checks that a mComp field is a number
export function checkValidMCompArg(field: any): void {
	if (typeof field !== "number") {
		// Reject if MComparison value is not a number
		throw new InsightError("MComparison Value is not a number");
	}
}

export function checkDir(dirBlock: any): void {
	checkExists(dirBlock, "dir in ORDER");
	checkString(dirBlock, "dir in ORDER");
	if (!Object.values(Direction).includes(dirBlock)) {
		throw new InsightError("ORDER dir is not a valid string (must be one of 'UP' or 'DOWN')");
	}
}

// Check that a field is consistent with an InsightDatasetKind. If not, throws InsightError
export function checkKind(field: string, datasetKind: string) {
	if (datasetKind !== InsightDatasetKind.Rooms && datasetKind !== InsightDatasetKind.Courses) {
		throw new InsightError("Invalid dataset kind reference");
	}
	if (datasetKind === InsightDatasetKind.Courses && !isCoursesField(field)) {
		// Reject if different dataset types are being referenced
		throw new InsightError("Multiple dataset types cannot be referred");
	}
	if (datasetKind === InsightDatasetKind.Rooms && !isRoomsField(field)) {
		// Reject if different dataset types are being referenced
		throw new InsightError("Multiple dataset types cannot be referred");
	}
}

// Throws InsightError if different dataset names are referenced.
export function checkDataset(datasetA: string, datasetB: string) {
	if (datasetA !== datasetB) {
		throw new InsightError("Multiple datasets cannot be referred");
	}
}

// Check if an applyObject is a valid applyRule. Otherwise, throws InsightError.
export function checkValidApplyRule(applyObj: any, validator: IQueryValidator): void {
	checkObjectLength(applyObj, 1, "APPLY RULE");
	let applyKey = Object.keys(applyObj)[0];
	validator.checkValidKey(applyKey, KeyType.APPLY_KEY);
	let token = Object.keys(applyObj[applyKey])[0];
	checkValidApplyToken(token);
	let key = applyObj[applyKey][token];
	validator.checkValidKey(key, KeyType.KEY);
	let keyField = key.split("_")[1];
	checkField(keyField, KeyType.KEY);
	checkValidTokenField(keyField, token);
}

// Checks if a field is a valid field for an ApplyToken. If not, throws InsightError
function checkValidTokenField(field: string, token: string) {
	if (token !== ApplyToken.COUNT && isSField(field)) {
		throw new InsightError(token + " requires a numeric field");
	}
}

// Check if an object exists. If not, throw InsightError
export function checkExists(obj: any, name: string) {
	if (!obj) {
		throw new InsightError("Missing " + name);
	}
}

// Sort a list of InsightResults by a tuple (orderKeys) and direction using insertion sort
export function orderResults(results: InsightResult[], orderKeys: string[], dir: string): InsightResult[] {
	// Sort by order
	for (let i = 1; i < results.length; i++) {
		let currentResultElement = results[i];
		let currentVariable = currentResultElement;
		let comparisonIndex = i - 1;
		while (comparisonIndex >= 0 && compareResults(results[comparisonIndex], currentVariable, orderKeys, dir)) {
			results[comparisonIndex + 1] = results[comparisonIndex];
			comparisonIndex = comparisonIndex - 1;
		}
		results[comparisonIndex + 1] = currentResultElement;
	}
	return results;
}

// Given a direction and orderKeys, returns:
// 	1	 if A comes before B
// 	0	 if A is tied with B
// -1	 if A comes after B
export function compareResults(
	resultA: InsightResult,
	resultB: InsightResult,
	orderKeys: string[],
	dir: string
): number {
	if (orderKeys.length === 1) {
		let key = orderKeys[0];
		if (resultA[key] === resultB[key]) {
			return 0;
		}
		switch (dir) {
			case Direction.UP:
				// A before B iff A < B
				if (resultA[key] < resultB[key]) {
					return 1;
				} else {
					return -1;
				}
			case Direction.DOWN:
				// A before B iff A > B
				if (resultA[key] > resultB[key]) {
					return 1;
				} else {
					return -1;
				}
			default:
				throw new InsightError("Invalid DIRECTION");
		}
	} else {
		let firstKeyComparison = compareResults(resultA, resultB, [orderKeys[0]], dir);
		if (firstKeyComparison !== 0) {
			return compareResults(resultA, resultB, orderKeys.splice(1), dir);
		} else {
			return firstKeyComparison;
		}
	}
}

import {InsightError} from "../IInsightFacade";
import {IKind} from "../interface/IKind";

// Class to extract filtered IKinds for a valid query
export class IPerformQuery {
	protected unchangedKinds: IKind[];
	protected filteredKinds: IKind[];

	constructor(kinds: IKind[], query: any) {
		this.unchangedKinds = kinds;
		this.filteredKinds = this.mainWhereFilter(query["WHERE"]);
	}

	public getFilteredKinds(): IKind[] {
		return this.filteredKinds;
	}

	private mainWhereFilter(filterBlock: any): IKind[] {
		if (Object.keys(filterBlock).length === 0) {
			// Empty WHERE block
			return this.unchangedKinds;
		}
		let finalResult: IKind[] = [];
		if (filterBlock["OR"] || filterBlock["AND"]) {
			let collatedResultArray: IKind[][] = [];
			if (filterBlock["OR"]) {
				const orBlock = filterBlock["OR"];
				for (let filter of orBlock) {
					let filteredArray = this.mainWhereFilter(filter);
					collatedResultArray.push(filteredArray);
				}
				finalResult = this.filterOr(collatedResultArray);
			} else {
				const andBlock = filterBlock["AND"];
				for (let filter of andBlock) {
					let filteredArray = this.mainWhereFilter(filter);
					collatedResultArray.push(filteredArray);
				}
				finalResult = this.filterAnd(collatedResultArray);
			}
		} else if (filterBlock["LT"] || filterBlock["EQ"] || filterBlock["GT"]) {
			// M Comparison
			finalResult = this.mComparison(filterBlock);
		} else if (filterBlock["IS"]) {
			// S Comparison
			finalResult = this.sComparison(filterBlock);
		} else if (filterBlock["NOT"]) {
			// Negation
			const negBlock = filterBlock["NOT"];
			let toBeExcludedArray: IKind[];
			toBeExcludedArray = this.mainWhereFilter(negBlock);
			// Remove the originally filtered kinds in NegBlock content (for negation):
			// https://stackoverflow.com/questions/19957348/remove-all-elements-contained-in-another-array
			finalResult = this.unchangedKinds.filter((kind) => {
				return !toBeExcludedArray.includes(kind);
			});
		}
		return finalResult;
	}

	private filterOr(collatedResultArray: IKind[][]): IKind[] {
		let finalArray: IKind[] = [];
		for (let currentArray of collatedResultArray) {
			finalArray = finalArray.concat(currentArray);
		}
		for (let i = 0; i < finalArray.length; ++i) {
			for (let j = i + 1; j < finalArray.length; ++j) {
				if (finalArray[i] === finalArray[j]) {
					finalArray.splice(j--, 1);
				}
			}
		}
		return finalArray;
	}

	private filterAnd(collatedResultArray: IKind[][]): IKind[] {
		let finalArray = collatedResultArray[0];
		for (let i = 1; i < collatedResultArray.length; i++) {
			finalArray = finalArray.filter((kind) => {
				return collatedResultArray[i].includes(kind);
			});
		}
		return finalArray;
	}

	private sComparison(filterBlock: any): IKind[] {
		const sComBlock = filterBlock["IS"];
		// Getting individual values
		const filterKey = Object.keys(sComBlock);
		const filterKeyString = filterKey[0];
		const splitKey = filterKeyString.split("_");
		const specificFieldKey = splitKey[1]; // one out of nine field keys
		const filterValue = sComBlock[filterKeyString]; // field value
		return this.unchangedKinds.filter((kind: any) => {
			return this.sCompFilterValueMatching(filterValue, kind, specificFieldKey);
		});
	}

	// Returns true if a kind's specified value matches a filter value
	private sCompFilterValueMatching(filterValue: string, kind: any, specificFieldKey: string): boolean {
		if (filterValue === "*") {
			return true;
		} else if (filterValue.startsWith("*") && filterValue.endsWith("*")) {
			return kind[specificFieldKey].includes(filterValue.substring(1, filterValue.length - 1));
		} else if (filterValue.startsWith("*")) {
			return kind[specificFieldKey].endsWith(filterValue.substring(1));
		} else if (filterValue.endsWith("*")) {
			return kind[specificFieldKey].startsWith(filterValue.substring(0, filterValue.length - 1));
		} else {
			return kind[specificFieldKey] === filterValue;
		}
	}

	private mComparison(filterBlock: any): IKind[] {
		let mComBlock: any;
		if (filterBlock["LT"]) {
			mComBlock = filterBlock["LT"];
		} else if (filterBlock["EQ"]) {
			mComBlock = filterBlock["EQ"];
		} else {
			mComBlock = filterBlock["GT"];
		}
		// Getting individual values
		const filterKey = Object.keys(mComBlock);
		const filterKeyString = filterKey[0];
		const splitKey = filterKeyString.split("_");
		const specificFieldKey = splitKey[1]; // one out of nine field keys
		const filterValue = mComBlock[filterKeyString]; // field value
		return this.mComparisonFilter(filterBlock, specificFieldKey, filterValue);
	}

	private mComparisonFilter(filterBlock: any, specificFieldKey: string, filterValue: any) {
		// New array
		return this.unchangedKinds.filter((item: any) => {
			if (specificFieldKey in item) {
				if (filterBlock["LT"]) {
					return item[specificFieldKey] < filterValue;
				} else if (filterBlock["EQ"]) {
					return item[specificFieldKey] === filterValue;
				} else {
					return item[specificFieldKey] > filterValue;
				}
			} else {
				// Reject if key is invalid
				throw new InsightError("Invalid key " + specificFieldKey);
			}
		});
	}
}

import {InsightDatasetKind, InsightError} from "../IInsightFacade";
import {
	checkDataset,
	checkDir,
	checkExists,
	checkField,
	checkKind,
	checkNonEmptyArray,
	checkObjectLength,
	checkString,
	checkSubset,
	checkValidApplyRule,
	checkValidMCompArg,
	checkValidSCompArg,
	Direction,
	hasUnderscore,
	isCoursesField,
	isRoomsField,
	KeyType,
} from "./IValidate";

// Class to validate query structure for InsightFacade
export class IQueryValidator {
	private datasetName: string = "";
	private datasetKind: string = "";
	private groupKeys: string[];
	private applyBlock: any;
	private readonly columnsArray: any;
	private readonly orderKeys: string[];
	private dir: string = Direction.UP; // Default to ascending order
	public readonly hasTransform: boolean;

	// Constructs a performQuery object
	constructor(query: any) {
		this.checkWhereBlock(query["WHERE"]);

		const optionsBlock = query["OPTIONS"];
		checkExists(optionsBlock, "OPTIONS");

		// Check TRANSFORMATIONS block
		const transformBlock = query["TRANSFORMATIONS"];
		this.hasTransform = false;
		this.groupKeys = [];
		if (transformBlock) {
			this.hasTransform = true;
			this.checkTransformBlock(transformBlock);
		}

		// Check COLUMNS, and check ORDER if it exists
		this.orderKeys = [];
		this.columnsArray = optionsBlock["COLUMNS"];
		this.checkColumnsArray();
		const orderBlock = optionsBlock["ORDER"];
		if (orderBlock) {
			this.orderKeys = this.extractOrderKeys(orderBlock);
		}
	}

	// Check that WHERE block is correctly formatted, including nested filters. Otherwise, throws an InsightError
	private checkWhereBlock(whereBlock: any) {
		checkExists(whereBlock, "WHERE");
		try {
			// Check if WHERE is empty
			checkObjectLength(whereBlock, 0, "WHERE");
		} catch (error) {
			if (error instanceof InsightError) {
				// WHERE should only have 1 arg
				checkObjectLength(whereBlock, 1, "WHERE");
				this.checkFilterBlock(whereBlock);
			} else {
				throw error;
			}
		}
	}

	private checkFilterBlock(block: any): void {
		if (block["OR"] || block["AND"]) {
			// Logic comparison
			checkObjectLength(block, 1, "AND/OR");
			let filterKey = Object.keys(block)[0];
			let filters = block[filterKey];
			checkNonEmptyArray(filters, "AND/OR args");
			filters.forEach((filter: any) => {
				this.checkFilterBlock(filter); // Recurse on nested filters
			});
		} else if (block["LT"] || block["EQ"] || block["GT"]) {
			// M Comparison
			checkObjectLength(block, 1, "LT/GT/EQ");
			let filterKey = Object.keys(block)[0];
			let mCompObj = block[filterKey];
			checkObjectLength(mCompObj, 1, "MCOMP");
			let mKey = Object.keys(mCompObj)[0];
			this.checkValidKey(mKey, KeyType.M_KEY);
			let mCompArg = mCompObj[mKey];
			checkValidMCompArg(mCompArg);
		} else if (block["IS"]) {
			// S Comparison
			checkObjectLength(block, 1, "IS");
			let sCompObj = block["IS"];
			checkObjectLength(sCompObj, 1, "SCOMP");
			let sKey = Object.keys(sCompObj)[0];
			this.checkValidKey(sKey, KeyType.S_KEY);
			let sCompArg = sCompObj[sKey];
			checkValidSCompArg(sCompArg);
		} else if (block["NOT"]) {
			// Negation
			const negBlock = block["NOT"];
			checkObjectLength(negBlock, 1, "NOT");
			this.checkFilterBlock(negBlock); // Recurse on nested filter
		} else {
			// Reject if invalid key
			throw new InsightError("Invalid filter");
		}
	}

	// Checks that a GROUP block is correctly formatted. Otherwise, throws InsightError
	private checkGroupBlock(groupBlock: any) {
		checkExists(groupBlock, "GROUP in TRANSFORMATIONS");
		checkNonEmptyArray(groupBlock, "GROUP");
		groupBlock.forEach((item: any) => {
			this.checkValidKey(item, KeyType.KEY);
		});
	}

	// Checks if COLUMNS block is correctly formatted and matches valid keys when valid keys is non-empty.
	// If not, throws InsightError.
	private checkColumnsArray(): void {
		checkExists(this.columnsArray, "COLUMNS");
		checkNonEmptyArray(this.columnsArray, "COLUMNS");
		let validKeys = this.groupKeys.concat(this.extractApplyKeys());
		if (validKeys.length > 0) {
			checkSubset(this.columnsArray, validKeys, "COLUMNS", "GROUP/APPLY");
		} else {
			this.columnsArray.forEach((columnKey: any) => {
				this.checkValidKey(columnKey, KeyType.KEY);
			});
		}
	}

	// Checks that an ORDER block is correctly formatted. If not, throws an InsightError
	private checkOrderBlock(orderBlock: any): void {
		if (typeof orderBlock === "string") {
			this.checkValidKey(orderBlock, KeyType.ANY_KEY);
		} else {
			// Case where order has 2 args
			checkObjectLength(orderBlock, 2, "ORDER");

			// Check that dir block is correct
			checkDir(orderBlock["dir"]);
			this.dir = orderBlock["dir"];

			// Check keys
			let keyArray = orderBlock["keys"];
			if (keyArray) {
				checkNonEmptyArray(keyArray, "ORDER keys");
				keyArray.forEach((key: any) => {
					this.checkValidKey(key, KeyType.ANY_KEY);
				});
			} else {
				throw new InsightError("ORDER block is missing keys");
			}
		}
	}

	// Returns the applyKey(s) of the applyBlock (if it exists). If any of the keys is invalid, throws an InsightError.
	private extractApplyKeys(): string[] {
		if (!this.applyBlock) {
			return [];
		}
		let extractedKeys: string[] = [];
		for (const item of this.applyBlock) {
			checkValidApplyRule(item, this);
			extractedKeys.push(Object.keys(item)[0]);
		}
		return extractedKeys;
	}

	// Checks that a TRANSFORMATIONS block is valid and extracts key(s). If not, throws an InsightError.
	private checkTransformBlock(transformBlock: any) {
		checkObjectLength(transformBlock, 2, "TRANSFORM");
		const groupBlock = transformBlock["GROUP"];
		this.checkGroupBlock(groupBlock);
		this.groupKeys = groupBlock;

		this.applyBlock = transformBlock["APPLY"];
		checkExists(this.applyBlock, "APPLY in TRANSFORMATIONS");
		// Note: APPLY is allowed to be an empty array
		if (!Array.isArray(this.applyBlock)) {
			throw new InsightError("APPLY is not an array");
		}
	}

	// Checks that an ORDER block is valid and returns the key(s). If the ORDER block or any keys is invalid, throws an InsightError.
	private extractOrderKeys(orderBlock: any): string[] {
		this.checkOrderBlock(orderBlock);
		let orderKeys;
		if (typeof orderBlock === "string") {
			orderKeys = [orderBlock];
		} else {
			orderKeys = orderBlock["keys"];
		}
		checkSubset(orderKeys, this.columnsArray, "ORDER", "COLUMNS");
		return orderKeys;
	}

	// Checks if a key is valid, given a KeyType. If not, throws InsightError
	public checkValidKey(key: any, keyType: KeyType): void {
		checkString(key, "Key");
		if (keyType === KeyType.KEY || keyType === KeyType.M_KEY || keyType === KeyType.S_KEY) {
			const splitKey = key.split("_");
			checkObjectLength(splitKey, 2, "Key");

			// Dataset check
			const specifiedDatasetName = splitKey[0];
			this.setDatasetName(specifiedDatasetName);
			checkDataset(specifiedDatasetName, this.datasetName);

			// Field check
			const specifiedField = splitKey[1];
			this.setDatasetKind(specifiedField);
			checkKind(specifiedField, this.datasetKind);
			if (keyType === KeyType.KEY) {
				// A valid key is a valid mkey or skey; check both
				try {
					checkField(specifiedField, KeyType.M_KEY);
				} catch (error) {
					if (error instanceof InsightError) {
						checkField(specifiedField, KeyType.S_KEY);
					} else {
						throw error;
					}
				}
			} else {
				checkField(specifiedField, keyType);
			}
		} else if (keyType === KeyType.ANY_KEY) {
			// Checks if a key is a valid anykey (key | applykey)
			try {
				this.checkValidKey(key, KeyType.KEY);
			} catch (error) {
				if (error instanceof InsightError) {
					this.checkValidKey(key, KeyType.APPLY_KEY);
				} else {
					throw error;
				}
			}
		} else if (keyType === KeyType.APPLY_KEY) {
			if (hasUnderscore(key)) {
				throw new InsightError("Apply key cannot contain underscores");
			}
		} else {
			throw new InsightError("Invalid KeyType");
		}
	}

	// If datasetName is not set, sets it to specifiedDatasetName
	public setDatasetName(specifiedDatasetName: string) {
		if (this.datasetName === "") {
			this.datasetName = specifiedDatasetName;
		}
	}

	// If datasetKind is not set, sets it using the given field
	public setDatasetKind(field: any) {
		if (this.datasetKind === "") {
			if (isCoursesField(field)) {
				this.datasetKind = InsightDatasetKind.Courses;
			} else if (isRoomsField(field)) {
				this.datasetKind = InsightDatasetKind.Rooms;
			} else {
				throw new InsightError("Invalid field");
			}
		}
	}

	public getDatasetName(): string {
		return this.datasetName;
	}

	public getDir(): string {
		return this.dir;
	}

	public getOrderKeys(): string[] {
		return this.orderKeys;
	}

	public getColumnsArray(): string[] {
		return this.columnsArray;
	}

	public getGroupKeys(): string[] {
		return this.groupKeys;
	}

	public getApplyRules(): string[] {
		return this.applyBlock;
	}
